record.field:
View = env['ir.ui.view'].sudo().with_context(active_test=False)
children = []
for xmlid in ('liber_login_aliases.login_alias_server_fallback', 'liber_login_aliases.login_alias_keep_typed'):
    child = env.ref(xmlid, raise_if_not_found=False)
    if child:
        children.append(child)
attached = 0
# 17.0.2.5.0: the browser-side lookup is gone - remove the lookup page and the old scripts (the importer never deletes)
for old in ('liber_login_aliases.page_login_alias_lookup', 'liber_login_aliases.login_alias_lookup', 'liber_login_aliases.login_alias_script'):
    rec = env.ref(old, raise_if_not_found=False)
    if rec:
        rec.sudo().unlink()
# the browser-side lookup was removed in 17.0.2.5.0: remove its copies from edited login pages
View.search([('key', 'like', 'liber_login_aliases_login_alias_script_site_%')]).unlink()
for site_copy in View.search([('key', '=', 'web.login'), ('website_id', '!=', False)]):
    for child in children:
        site_key = '%s_site_%s' % (child.key.replace('.', '_'), site_copy.website_id.id)
        existing = View.search([('key', '=', site_key)], limit=1)
        vals = {'name': '%s (%s)' % (child.name, site_copy.website_id.name), 'type': 'qweb', 'key': site_key, 'mode': 'extension', 'priority': child.priority,
                'inherit_id': site_copy.id, 'website_id': site_copy.website_id.id, 'arch_db': child.arch_db,
                'active': child.active}
        if existing:
            existing.write(vals)
        else:
            View.create(vals)
        attached += 1
log("Liber Login Aliases: attached to %s website login page copies" % attached)
